import { Group, Mesh, PlaneGeometry, AmbientLight, DirectionalLight, Color, MeshStandardNodeMaterial, MathUtils } from 'three/webgpu';
import { uv, mix, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const {
    THREE: {
      Group,
      Mesh,
      PlaneGeometry,
      AmbientLight,
      DirectionalLight,
      Color,
      MeshStandardNodeMaterial,
      MathUtils,
    },
    textureLoader,
    emit,
    primitives,
    fontAtlas,
  } = ctx;

  const disposables = [];

  // Root group
  const root = new Group();

  // ---------- Backdrop with vertical gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  const gradStart = color('#0b0b10');
  const gradEnd = color('#12121a');
  backdropMat.colorNode = mix(gradStart, gradEnd, uv().y);
  backdropMat.roughness = 1;
  backdropMat.metalness = 0;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeom, backdropMat);

  // ---------- Lights ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(5, 5, 5);
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-5, -3, -2);
  root.add(ambient, keyLight, rimLight);

  // ---------- Filmstrip ----------
  const strip = new Group();
  strip.rotation.y = MathUtils.degToRad(-18);
  root.add(strip);

  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const bevel = 0.025;
  const pitch = 1.85;
  const focusIndex = 2; // middle card
  const inkColor = new Color('#16161d');

  // Load shared texture (all cards share the same texture due to asset limits)
  let sharedTexture = null;
  const texturePromise = textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    sharedTexture = tex;
    innerMeshes.forEach((mesh) => {
      mesh.material.map = tex;
      mesh.material.needsUpdate = true;
    });
  });

  const innerMeshes = [];

  for (let i = 0; i < 5; i++) {
    const cardGroup = new Group();
    const xPos = (i - 2) * pitch;
    cardGroup.position.x = xPos;

    // Outer bevel plane (ink color)
    const outerGeom = new PlaneGeometry(cardWidth + bevel * 2, cardHeight + bevel * 2);
    const outerMat = new MeshStandardNodeMaterial();
    outerMat.color = inkColor;
    outerMat.roughness = 0.55;
    outerMat.metalness = 0.2;
    outerMat.clearcoat = 0.15;
    const outer = new Mesh(outerGeom, outerMat);
    cardGroup.add(outer);
    disposables.push(outerGeom, outerMat);

    // Inner textured plane
    const innerGeom = new PlaneGeometry(cardWidth, cardHeight);
    const innerMat = new MeshStandardNodeMaterial();
    innerMat.roughness = 0.55;
    innerMat.metalness = 0.2;
    innerMat.clearcoat = 0.15;
    innerMat.transparent = true;
    const inner = new Mesh(innerGeom, innerMat);
    inner.position.z = 0.001;
    cardGroup.add(inner);
    disposables.push(innerGeom, innerMat);
    innerMeshes.push(inner);

    // Scale & opacity based on focus
    const isFocused = i === focusIndex;
    const scaleFactor = isFocused ? 1.0 : 0.92;
    cardGroup.scale.setScalar(scaleFactor);
    inner.material.opacity = isFocused ? 1.0 : MathUtils.lerp(1.0, 0.55, Math.abs(i - focusIndex) / 2);

    // Underline for focused card
    if (isFocused) {
      const underlineGeom = new PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial();
      underlineMat.emissiveColorNode = color('#ff2a38');
      underlineMat.emissiveIntensityNode = float(1.3);
      underlineMat.transparent = true;
      const underline = new Mesh(underlineGeom, underlineMat);
      underline.position.set(0, -cardHeight / 2 - 0.035 / 2 - 0.05, 0.002);
      cardGroup.add(underline);
      disposables.push(underlineGeom, underlineMat);
    }

    strip.add(cardGroup);
  }

  // ---------- Apply cinematic primitive ----------
  const parallaxPrim = primitives['parallax-scroll'](strip, { intensity: 0.5 });
  disposables.push(parallaxPrim);

  // ---------- Text elements ----------
  const headline = fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  const captions = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];
  captions.forEach((txt, idx) => {
    const cap = fontAtlas.createText(txt, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    });
    const x = (idx - 2) * pitch;
    const y = -cardHeight / 2 - 0.125; // 0.25 unit rhythm from card bottom
    cap.position.set(x, y, 0);
    root.add(cap);
  });

  // ---------- Cleanup ----------
  root.userData.handlers = {}; // No interactive handlers required
  root.userData.cleanup = () => {
    disposables.forEach((obj) => {
      if (obj && typeof obj.dispose === 'function') obj.dispose();
      if (obj && typeof obj.cleanup === 'function') obj.cleanup();
    });
    if (sharedTexture && typeof sharedTexture.dispose === 'function') {
      sharedTexture.dispose();
    }
    // Ensure GSAP timelines are killed (none directly created here, but primitives may have)
    gsap.globalTimeline.clear();
  };

  return root;
}
